INSERT INTO transcript_segments (id,meeting_id,segment_index,speaker_name,start_ms,end_ms,content) VALUES
('a59eba31-6811-5c94-ba30-e98cbe714e8a','2033cb92-95e6-5580-a51a-b199bbb8b69f','0','Maya Chen','0','30000','We want to start Smart Routing with ten merchants. The goal is to improve authorisation performance without changing the merchant integration.'),
('a20bb55a-1cff-5f7b-8595-046027f9d8c4','2033cb92-95e6-5580-a51a-b199bbb8b69f','1','Maya Chen','30000','60000','Let''s begin with a 5% canary. Expansion requires reliability and risk checks to pass.'),
('26f7cf55-f7dd-500e-b66a-ff2e0d6ae338','ea655bba-f14e-521d-8ec8-458fa2398acb','0','Daniel Foster','0','30000','A processor timeout does not prove that the processor never received or authorised the payment.'),
('b9db6072-0a38-519b-997e-ced2205960a6','ea655bba-f14e-521d-8ec8-458fa2398acb','1','Elena Petrova','30000','60000','Carry the same idempotency key across routing and processor attempts. Do not automatically fail over an ambiguous timeout until we have safe reconciliation.'),
('0c746951-71fe-5254-944b-77bd554c1119','2e061b40-a4e5-5f67-9b70-01ed58328916','0','Omar Hassan','0','30000','Routing to a secondary processor must not bypass the risk decision for the original transaction.'),
('a083c899-d1ed-5d42-8764-ceb0676c6fa8','2e061b40-a4e5-5f67-9b70-01ed58328916','1','Fatima Ali','30000','60000','Risk evaluation must be independent of processor selection. If mandatory risk evaluation is unavailable, fail safely rather than routing around it.'),
('2d03a083-b362-519f-bc00-c9bd82c0bcb8','35623284-e53b-538f-a88f-719ceb2ad5b2','0','James Wilson','0','30000','The routing service must never write raw card numbers or sensitive authentication data into application logs.'),
('adca6eeb-576c-5489-bfb9-ec35e82f2ea3','35623284-e53b-538f-a88f-719ceb2ad5b2','1','Nina Patel','30000','60000','Review error traces, retry metadata, tokenised references, access controls, and the updated PCI data-flow documentation.'),
('eafbd7e0-04c2-52b3-a153-c21db4afc51b','880f34a1-35bd-5796-8ab1-ad4d662edcec','0','Priya Nair','0','30000','The canary dashboard needs p95 latency, processor timeout rate, error rate, and traffic distribution.'),
('b3ff4c2a-573e-536d-a9d0-71a7234e89d1','880f34a1-35bd-5796-8ab1-ad4d662edcec','1','Priya Nair','30000','60000','For this pilot, pause expansion if p95 latency exceeds 650 ms for ten minutes or the error rate exceeds 0.5%. Pause does not automatically mean rollback.'),
('28e03116-b81d-5488-83b2-bbc2825892ff','a125dfc8-e498-5898-8dfa-e4acf91fb697','0','Priya Nair','0','30000','The pilot showed elevated processor timeouts and rising p95 latency. We should not expand traffic.'),
('07068749-1e7f-5e76-8179-5981e72299cc','a125dfc8-e498-5898-8dfa-e4acf91fb697','1','Elena Petrova','30000','60000','Some requests are retried even though we cannot tell whether the original processor completed authorisation. Disable automatic cross-processor retries for ambiguous outcomes.'),
('45b73067-a55d-5922-8507-fe9cd9c710f8','69e18c75-f04d-528e-8087-1aa642142c06','0','Priya Nair','0','30000','Timeout behaviour is not ready. Risk verification and monitoring validation are also incomplete.'),
('d6739a44-b1d0-5930-a4f6-70bbce1723bb','69e18c75-f04d-528e-8087-1aa642142c06','1','Maya Chen','30000','60000','Replace the planned 20% expansion date with a 14 November readiness review. Payments, SRE, Risk, and Security must approve before expansion.'),
('6b6ef3bc-feec-593d-8080-f5b96c52639d','75294199-1a00-5b40-928f-75d96eaa8dda','0','Sarah Kim','0','30000','Merchants need a clear explanation and a support runbook for payment failures during the pilot.'),
('c7ffd5af-d1a9-50ba-a5a3-a5bcfe6d2aee','75294199-1a00-5b40-928f-75d96eaa8dda','1','Maya Chen','30000','60000','Keep merchant communication in draft. Do not confirm the expansion date until the technical readiness review is approved.');
INSERT INTO evidence (id,organisation_id,meeting_id,transcript_segment_id,start_offset,end_offset,quote,speaker_name,start_ms,end_ms,created_at) VALUES
('2c3825f0-290f-55f3-9e1f-12e8a7a2a13e','c12d3609-5d89-5d41-99f9-20b2a8f15321','2033cb92-95e6-5580-a51a-b199bbb8b69f','a59eba31-6811-5c94-ba30-e98cbe714e8a','0','142','We want to start Smart Routing with ten merchants. The goal is to improve authorisation performance without changing the merchant integration.','Maya Chen','0','30000','2026-10-31T09:00:00+05:30'),
('664e7b8e-c346-5342-96d8-a12df6055286','c12d3609-5d89-5d41-99f9-20b2a8f15321','2033cb92-95e6-5580-a51a-b199bbb8b69f','a20bb55a-1cff-5f7b-8595-046027f9d8c4','0','85','Let''s begin with a 5% canary. Expansion requires reliability and risk checks to pass.','Maya Chen','30000','60000','2026-10-31T09:00:00+05:30'),
('d936e366-758c-5a1e-bddd-9a16cef8d8c7','c12d3609-5d89-5d41-99f9-20b2a8f15321','ea655bba-f14e-521d-8ec8-458fa2398acb','26f7cf55-f7dd-500e-b66a-ff2e0d6ae338','0','95','A processor timeout does not prove that the processor never received or authorised the payment.','Daniel Foster','0','30000','2026-10-31T09:00:00+05:30'),
('b4c842f9-a72a-58f9-8aab-71916c6bed36','c12d3609-5d89-5d41-99f9-20b2a8f15321','ea655bba-f14e-521d-8ec8-458fa2398acb','b9db6072-0a38-519b-997e-ced2205960a6','0','156','Carry the same idempotency key across routing and processor attempts. Do not automatically fail over an ambiguous timeout until we have safe reconciliation.','Elena Petrova','30000','60000','2026-10-31T09:00:00+05:30'),
('0637ca22-195d-529a-b9e1-293ed50e61e0','c12d3609-5d89-5d41-99f9-20b2a8f15321','2e061b40-a4e5-5f67-9b70-01ed58328916','0c746951-71fe-5254-944b-77bd554c1119','0','96','Routing to a secondary processor must not bypass the risk decision for the original transaction.','Omar Hassan','0','30000','2026-10-31T09:00:00+05:30'),
('246e8b18-85c4-582d-a08c-16a72456e55c','c12d3609-5d89-5d41-99f9-20b2a8f15321','2e061b40-a4e5-5f67-9b70-01ed58328916','a083c899-d1ed-5d42-8764-ceb0676c6fa8','0','147','Risk evaluation must be independent of processor selection. If mandatory risk evaluation is unavailable, fail safely rather than routing around it.','Fatima Ali','30000','60000','2026-10-31T09:00:00+05:30'),
('2b9aa0e1-dc42-5e62-a9a1-6748c791e937','c12d3609-5d89-5d41-99f9-20b2a8f15321','35623284-e53b-538f-a88f-719ceb2ad5b2','2d03a083-b362-519f-bc00-c9bd82c0bcb8','0','109','The routing service must never write raw card numbers or sensitive authentication data into application logs.','James Wilson','0','30000','2026-10-31T09:00:00+05:30'),
('227bd71b-b9bb-55f7-97c3-227117acb647','c12d3609-5d89-5d41-99f9-20b2a8f15321','35623284-e53b-538f-a88f-719ceb2ad5b2','adca6eeb-576c-5489-bfb9-ec35e82f2ea3','0','120','Review error traces, retry metadata, tokenised references, access controls, and the updated PCI data-flow documentation.','Nina Patel','30000','60000','2026-10-31T09:00:00+05:30'),
('c448f4ab-c8a8-56ba-8392-6070a259b6d7','c12d3609-5d89-5d41-99f9-20b2a8f15321','880f34a1-35bd-5796-8ab1-ad4d662edcec','eafbd7e0-04c2-52b3-a153-c21db4afc51b','0','101','The canary dashboard needs p95 latency, processor timeout rate, error rate, and traffic distribution.','Priya Nair','0','30000','2026-10-31T09:00:00+05:30'),
('9a983b63-3633-545d-ae12-4764d3abde6a','c12d3609-5d89-5d41-99f9-20b2a8f15321','880f34a1-35bd-5796-8ab1-ad4d662edcec','b3ff4c2a-573e-536d-a9d0-71a7234e89d1','0','153','For this pilot, pause expansion if p95 latency exceeds 650 ms for ten minutes or the error rate exceeds 0.5%. Pause does not automatically mean rollback.','Priya Nair','30000','60000','2026-10-31T09:00:00+05:30'),
('ae6a58f9-4fd9-59c6-8993-3d00282d09f3','c12d3609-5d89-5d41-99f9-20b2a8f15321','a125dfc8-e498-5898-8dfa-e4acf91fb697','28e03116-b81d-5488-83b2-bbc2825892ff','0','98','The pilot showed elevated processor timeouts and rising p95 latency. We should not expand traffic.','Priya Nair','0','30000','2026-10-31T09:00:00+05:30'),
('0f5c1976-c943-5125-976f-99250b02ea5d','c12d3609-5d89-5d41-99f9-20b2a8f15321','a125dfc8-e498-5898-8dfa-e4acf91fb697','07068749-1e7f-5e76-8179-5981e72299cc','0','174','Some requests are retried even though we cannot tell whether the original processor completed authorisation. Disable automatic cross-processor retries for ambiguous outcomes.','Elena Petrova','30000','60000','2026-10-31T09:00:00+05:30'),
('b24abf70-3628-5587-9838-090e0dec1b0c','c12d3609-5d89-5d41-99f9-20b2a8f15321','69e18c75-f04d-528e-8087-1aa642142c06','45b73067-a55d-5922-8507-fe9cd9c710f8','0','96','Timeout behaviour is not ready. Risk verification and monitoring validation are also incomplete.','Priya Nair','0','30000','2026-10-31T09:00:00+05:30'),
('a6f6412a-013f-5589-9cbf-e5c94d4884ae','c12d3609-5d89-5d41-99f9-20b2a8f15321','69e18c75-f04d-528e-8087-1aa642142c06','d6739a44-b1d0-5930-a4f6-70bbce1723bb','0','140','Replace the planned 20% expansion date with a 14 November readiness review. Payments, SRE, Risk, and Security must approve before expansion.','Maya Chen','30000','60000','2026-10-31T09:00:00+05:30'),
('b2c23255-e663-5e56-955c-0feed9947a9b','c12d3609-5d89-5d41-99f9-20b2a8f15321','75294199-1a00-5b40-928f-75d96eaa8dda','6b6ef3bc-feec-593d-8080-f5b96c52639d','0','95','Merchants need a clear explanation and a support runbook for payment failures during the pilot.','Sarah Kim','0','30000','2026-10-31T09:00:00+05:30'),
('faf03243-d9f8-541e-9f90-6f3eb33e61d2','c12d3609-5d89-5d41-99f9-20b2a8f15321','75294199-1a00-5b40-928f-75d96eaa8dda','c7ffd5af-d1a9-50ba-a5a3-a5bcfe6d2aee','0','121','Keep merchant communication in draft. Do not confirm the expansion date until the technical readiness review is approved.','Maya Chen','30000','60000','2026-10-31T09:00:00+05:30');
